type AsientosCsv200ApplicationoctetStreamResponse struct {
	Body          io.Reader
	ContentLength int64
}

func (response AsientosCsv200ApplicationoctetStreamResponse) VisitAsientosCsvResponse(w http.ResponseWriter) error {

	w.Header().Set("Content-Type", "application/octet-stream")
	if response.ContentLength != 0 {
		w.Header().Set("Content-Length", fmt.Sprint(response.ContentLength))
	}
	w.WriteHeader(200)

	if closer, ok := response.Body.(io.ReadCloser); ok {
		defer closer.Close()
	}
	_, err := io.Copy(w, response.Body)
	return err
}

